package com.example.ClaimShieldX.documents.storage;

import com.example.ClaimShieldX.exceptions.StorageObjectNotFoundException;
import com.example.ClaimShieldX.exceptions.StorageUnavailableException;

import java.io.InputStream;

/**
 * Private store for original uploaded files. Keys are generated by the server and never derived from a
 * client-supplied name. Implementations must refuse to overwrite an existing object.
 */
public interface DocumentStorage {
    /** Stores exactly {@code sizeBytes} bytes read from {@code content}. The caller keeps ownership of the stream. */
    void put(String objectKey, InputStream content, long sizeBytes, String contentType) throws StorageUnavailableException;

    /** The caller must close the returned stream. */
    InputStream open(String objectKey) throws StorageObjectNotFoundException, StorageUnavailableException;

    /** Idempotent: deleting a missing object is not an error. */
    void delete(String objectKey) throws StorageUnavailableException;
}
